import React from 'react';

const AdminLoading = ({
  fullScreen = false,
  label = 'Loading',
  compact = false,
}) => {
  if (compact) {
    return (
      <div className="flex min-h-[180px] items-center justify-center" role="status" aria-live="polite">
        <div className="text-center">
          <div className="admin-loader-ring mx-auto h-10 w-10" />
          <p className="mt-3 text-xs font-semibold text-slate-500">{label}</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`${fullScreen ? 'fixed inset-0 z-[100]' : 'absolute inset-0 z-30'} flex items-center justify-center overflow-hidden bg-[#f4f7fb]/95 backdrop-blur-sm`}
      role="status"
      aria-live="polite"
    >
      <div className="absolute -left-20 top-1/4 h-64 w-64 rounded-full bg-blue-500/10 blur-3xl" />
      <div className="absolute -right-20 bottom-1/4 h-64 w-64 rounded-full bg-red-500/10 blur-3xl" />

      <div className="relative text-center">
        <div className="relative mx-auto flex h-24 w-24 items-center justify-center">
          <div className="absolute inset-0 rounded-[28px] bg-gradient-to-br from-blue-950 to-blue-700 shadow-2xl shadow-blue-950/20" />
          <div className="absolute -inset-2 animate-ping rounded-[32px] border border-blue-400/20" />
          <div className="relative text-2xl font-black tracking-tight text-white">
            <span className="text-red-500">SC</span>
          </div>
          <span className="absolute -bottom-2 -right-2 h-7 w-7 rounded-full border-4 border-[#f4f7fb] bg-emerald-400 shadow-lg" />
        </div>

        <h2 className="mt-7 text-lg font-black tracking-tight text-slate-900">SC Academy Admin</h2>
        <p className="mt-1 text-sm font-medium text-slate-500">{label}</p>

        <div className="mx-auto mt-6 h-1.5 w-44 overflow-hidden rounded-full bg-slate-200">
          <div className="admin-loader-bar h-full rounded-full bg-gradient-to-r from-blue-800 via-blue-500 to-red-500" />
        </div>
      </div>
    </div>
  );
};

export default AdminLoading;
